import{_ as a,a0 as p,w as L,s,ao as i,I as l,x as e,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"LKRG：用於運行時完整性檢查的可加載內核模組 | LCTT x X-CMD","titleTemplate":false,"description":"LKRG：用於運行時完整性檢查的可加載內核模組 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LKRG：用於運行時完整性檢查的可加載內核模組 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LKRG：用於運行時完整性檢查的可加載內核模組 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180204 LKRG- Linux to Get a Loadable Kernel Module for Runtime Integrity Checking","title":"LKRG：用於運行時完整性檢查的可加載內核模組","tag":"201803","desc":""},"relativePath":"201803/20180204 LKRG- Linux to Get a Loadable Kernel Module for Runtime Integrity Checking.md","filePath":"[post].md"}'),u={name:"201803/20180204 LKRG- Linux to Get a Loadable Kernel Module for Runtime Integrity Checking.md"};function d(K,t,R,G,g,m){const n=p("Link");return L(),s("div",null,[t[20]||(t[20]=i('<h1 id="lkrg-用於運行時完整性檢查的可加載內核模組" tabindex="-1">LKRG：用於運行時完整性檢查的可加載內核模組 <a class="header-anchor" href="#lkrg-用於運行時完整性檢查的可加載內核模組" aria-label="Permalink to “LKRG：用於運行時完整性檢查的可加載內核模組”">​</a></h1><p><img src="https://www.bleepstatic.com/content/posts/2018/02/04/LKRG-logo.png" alt="LKRG logo"></p><p>開源社區的人們正在致力於一個 Linux 內核的新項目，它可以讓內核更安全。命名為 Linux 內核運行時防護（Linux Kernel Runtime Guard，簡稱：LKRG），它是一個在 Linux 內核執行運行時完整性檢查的可加載內核模組（LKM）。</p><p>它的用途是檢測對 Linux 內核的已知的或未知的安全漏洞利用企圖，以及去阻止這種攻擊企圖。</p><p>LKRG 也可以檢測正在運行的進程的提權行為，在漏洞利用代碼運行之前殺掉這個運行進程。</p><h3 id="這個項目開發始於-2011-年-首個版本已經發布" tabindex="-1">這個項目開發始於 2011 年，首個版本已經發布 <a class="header-anchor" href="#這個項目開發始於-2011-年-首個版本已經發布" aria-label="Permalink to “這個項目開發始於 2011 年，首個版本已經發布”">​</a></h3><p>因為這個項目開發的較早，LKRG 的當前版本僅僅是通過內核消息去報告違反內核完整性的行為，但是隨着這個項目的成熟，將會部署一個完整的漏洞利用緩減系統。</p><p>LKRG 的成員 Alexander Peslyak 解釋説，這個項目從 2011 年啓動，並且 LKRG 已經經歷了一個“重新開發&quot;階段。</p>',8)),l("p",null,[t[3]||(t[3]=e("LKRG 的首個公開版本是 LKRG v0.0，它現在可以從 ",-1)),r(n,{href:"http://www.openwall.com/lkrg/"},{default:o(()=>[...t[0]||(t[0]=[e("這個頁面",-1)])]),_:1}),t[4]||(t[4]=e(" 下載使用。",-1)),r(n,{href:"http://openwall.info/wiki/p_lkrg/Main"},{default:o(()=>[...t[1]||(t[1]=[e("這裏",-1)])]),_:1}),t[5]||(t[5]=e(" 是這個項目的維基，為支持這個項目，它也有一個 ",-1)),r(n,{href:"https://www.patreon.com/p_lkrg"},{default:o(()=>[...t[2]||(t[2]=[e("Patreon 頁面",-1)])]),_:1}),t[6]||(t[6]=e("。",-1))]),t[21]||(t[21]=i('<p>雖然 LKRG 仍然是一個開源項目，LKRG 的維護者也計劃做一個 LKRG Pro 版本，這個版本將包含一個專用的 LKRG 發行版，它將支持對特定漏洞利用的檢測，比如，容器泄漏。開發團隊計劃從 LKRG Pro 基金中提取部分資金用於保證項目的剩餘工作。</p><h3 id="lkrg-是一個內核模組而不是一個補丁。" tabindex="-1">LKRG 是一個內核模組而不是一個補丁。 <a class="header-anchor" href="#lkrg-是一個內核模組而不是一個補丁。" aria-label="Permalink to “LKRG 是一個內核模組而不是一個補丁。”">​</a></h3><p>一個類似的項目是<ruby>附加內核監視器<rt>Additional Kernel Observer</rt></ruby>（AKO），但是 LKRG 與 AKO 是不一樣的，因為 LKRG 是一個內核加載模組而不是一個補丁。LKRG 開發團隊決定將它設計為一個內核模組是因為，在內核上打補丁對安全性、系統穩定性以及性能都有很直接的影響。</p><p>而以內核模組的方式提供，可以在每個系統上更容易部署 LKRG，而不必去修改核心的內核代碼，修改核心的內核代碼非常複雜並且很容易出錯。</p><p>LKRG 內核模組在目前主流的 Linux 發行版上都可以使用，比如，RHEL7、OpenVZ 7、Virtuozzo 7、以及 Ubuntu 16.04 到最新的主線版本。</p><h3 id="它並非是一個完美的解決方案" tabindex="-1">它並非是一個完美的解決方案 <a class="header-anchor" href="#它並非是一個完美的解決方案" aria-label="Permalink to “它並非是一個完美的解決方案”">​</a></h3><p>LKRG 的創建者警告用户，他們並不認為 LKRG 是一個完美的解決方案，它<strong>提供不了</strong>堅不可摧和 100% 的安全。他們説，LKRG 是 “設計為<strong>可旁通</strong>的”，並且僅僅提供了“多元化安全” 的<strong>一個</strong>方面。</p><blockquote><p>雖然 LKRG 可以防禦許多已有的 Linux 內核漏洞利用，而且也有可能會防禦將來許多的（包括未知的）未特意設計去繞過 LKRG 的安全漏洞利用。它是設計為可旁通的（儘管有時候是以更復雜和/或低可利用為代價的）。因此，他們説 LKRG 通過多元化提供安全，就像運行一個不常見的操作系統內核一樣，也就不會有真實運行一個不常見的操作系統的可用性弊端。</p></blockquote><p>LKRG 有點像基於 Windows 的防病毒軟件，它也是工作於內核級別去檢測漏洞利用和惡意軟件。但是，LKRG 團隊説，他們的產品比防病毒軟件以及其它終端安全軟件更加安全，因為它的基礎代碼量比較小，所以在內核級別引入新 bug 和漏洞的可能性就更小。</p><h3 id="運行當前版本的-lkrg-大約會帶來-6-5-的性能損失" tabindex="-1">運行當前版本的 LKRG 大約會帶來 6.5% 的性能損失 <a class="header-anchor" href="#運行當前版本的-lkrg-大約會帶來-6-5-的性能損失" aria-label="Permalink to “運行當前版本的 LKRG 大約會帶來 6.5% 的性能損失”">​</a></h3><p>Peslyak 説 LKRG 是非常適用於 Linux 機器的，它在修補內核的安全漏洞後不需要重啓動機器。LKRG 允許用户持續運行帶有安全措施的機器，直到在一個計劃的維護窗口中測試和部署關鍵的安全補丁為止。</p><p>經測試顯示，安裝 LKRG v0.0 後大約會產生 6.5% 性能影響，但是，Peslyak 説將在後續的開發中持續降低這種影響。</p><p>測試也顯示，LKRG 檢測到了 CVE-2014-9322 (BadIRET)、CVE-2017-5123 (waitid(2) missing access_ok)、以及 CVE-2017-6074 (use-after-free in DCCP protocol) 的漏洞利用企圖，但是沒有檢測到 CVE-2016-5195 (Dirty COW) 的漏洞利用企圖。開發團隊説，由於前面提到的“可旁通”的設計策略，LKRG 沒有檢測到 Dirty COW 提權攻擊。</p><blockquote><p>在 Dirty COW 的測試案例中，由於 bug 機制的原因，使得 LKRG 發生了 “旁通”，並且這也是一種利用方法，它也是將來類似的以用户空間為目標的繞過 LKRG 的一種方法。這樣的漏洞利用是否會是普通情況（不太可能！除非 LKRG 或者類似機制的軟件流行起來），以及對它的可用性的（負面的）影響是什麼？（對於那些直接目標是用户空間的內核漏洞來説，這不太重要，也並不簡單）。</p></blockquote><hr>',15)),l("p",null,[t[8]||(t[8]=e("via: ",-1)),r(n,{href:"https://www.bleepingcomputer.com/news/linux/lkrg-linux-to-get-a-loadable-kernel-module-for-runtime-integrity-checking/"},{default:o(()=>[...t[7]||(t[7]=[e("https://www.bleepingcomputer.com/news/linux/lkrg-linux-to-get-a-loadable-kernel-module-for-runtime-integrity-checking/",-1)])]),_:1})]),l("p",null,[t[12]||(t[12]=e("作者：",-1)),r(n,{href:"https://www.bleepingcomputer.com/author/catalin-cimpanu/"},{default:o(()=>[...t[9]||(t[9]=[e("Catalin Cimpanu",-1)])]),_:1}),t[13]||(t[13]=e(" 譯者：",-1)),r(n,{href:"https://github.com/qhwdw"},{default:o(()=>[...t[10]||(t[10]=[e("qhwdw",-1)])]),_:1}),t[14]||(t[14]=e(" 校對：",-1)),r(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[11]||(t[11]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[17]||(t[17]=e("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[15]||(t[15]=[e("LCTT",-1)])]),_:1}),t[18]||(t[18]=e(" 原創編譯，",-1)),r(n,{href:"https://linux.cn/"},{default:o(()=>[...t[16]||(t[16]=[e("Linux中國",-1)])]),_:1}),t[19]||(t[19]=e(" 榮譽推出",-1))])])}const b=a(u,[["render",d]]);export{x as __pageData,b as default};
